# Registers blog-x-following-reply-task: replies to recent posts from accounts @100labjtvn
# follows, and to replies that come back on our own replies. The reply text is generated by
# scripts/x_llm.py (gemini-3.5-flash-lite -> longcat-2.5-free -> claude haiku fallback chain).
#
# Runs every 45 minutes. Unlike run-claude-task.ps1 this needs no wrapper mutex: the Python
# script itself acquires "Local\kingsworksub-blog-x-jobs" per cycle (10s wait) and skips the
# cycle when another X job is running, so a wrapper lock would only add a second wait.
#
# Kept ASCII-only: Windows PowerShell 5.1 reads BOM-less UTF-8 .ps1 files as ANSI and breaks on
# Japanese string literals (same reason as schedule-unfollow.ps1).
#
# Usage: powershell -NoProfile -ExecutionPolicy Bypass -File scripts/schedule-following-reply.ps1
#        Disable-ScheduledTask -TaskName blog-x-following-reply-task   # to pause it

$taskName = "blog-x-following-reply-task"
$repo = "C:\Users\norio\my-github-blog"
$pythonPath = (Get-Command python).Source
$log = Join-Path $repo "scripts\scheduled\logs\x-following-reply.log"
New-Item -ItemType Directory -Force -Path (Split-Path $log) | Out-Null

# RepetitionDuration must be a plain span (TimeSpan::MaxValue is rejected by Task Scheduler).
$trigger = New-ScheduledTaskTrigger -Once -At "00:05" `
    -RepetitionInterval (New-TimeSpan -Minutes 45) `
    -RepetitionDuration (New-TimeSpan -Days 3650)
$action = New-ScheduledTaskAction -Execute $pythonPath `
    -Argument "scripts\x-following-reply.py --publish --log-file `"$log`"" `
    -WorkingDirectory $repo
$settings = New-ScheduledTaskSettingsSet -StartWhenAvailable -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries `
    -RunOnlyIfNetworkAvailable -MultipleInstances IgnoreNew -ExecutionTimeLimit (New-TimeSpan -Minutes 30)
$principal = New-ScheduledTaskPrincipal -UserId "$env:USERDOMAIN\$env:USERNAME" -LogonType Interactive -RunLevel Limited

Register-ScheduledTask -TaskName $taskName -Trigger $trigger -Action $action -Settings $settings `
    -Principal $principal `
    -Description "X: reply to posts from followed accounts and to replies on our replies (max 3/cycle, 20/day)" `
    -Force | Out-Null

Write-Host "registered $taskName (every 45 min, log: $log)"
Get-ScheduledTask -TaskName $taskName | Get-ScheduledTaskInfo | Select-Object TaskName, NextRunTime, LastTaskResult
